let supportsDraft=null;
function supportRule(g,id){const base=SUPPORT_DEFINITIONS[id],r=g.supportRules?.[id]||{};return{target:id==='protein'&&r.followPlan!==false&&state.settings.macros?.p?state.settings.macros.p:r.target||base.target,followPlan:id==='protein'&&r.followPlan!==false,needsPlan:id==='protein'&&r.followPlan!==false&&!state.settings.macros?.p,label:r.label||base.name,days:Array.isArray(r.days)?r.days:[0,1,2,3,4,5,6],automatic:r.automatic===undefined?!!base.auto:r.automatic};}
function supportStatus(g,id,d=selectedDate){const def=SUPPORT_DEFINITIONS[id],r=supportRule(g,id),l=state.logs[d]||{},planned=r.days.includes(dt(d).getUTCDay());let value=null;if(r.automatic){const mv=movementTotals(d);value=({meals:()=>l.meals?.length||null,minutes:()=>mv.minutes||null,steps:()=>l.steps||null,water:()=>l.water?l.water*250:null,sleep:()=>l.sleep?1:null,checkin:()=>l.checkIn?1:null,protein:()=>macroCoverage(d).p.complete?totals(d).p:null,strength:()=>l.workouts?.filter(w=>['met-02054','met-02050','met-02052','met-02057','met-02022','met-02040','met-02035'].includes(w.activityId)).length||null,mobility:()=>l.workouts?.filter(w=>activityById(w.activityId)?.category==='restore').reduce((s,w)=>s+w.minutes,0)||null}[def.auto]||(()=>null))();}else{value=l.supportValues?.[g.id+'__'+id]??(!g.supportRules?.[id]&&l.habits?.[id]?r.target:null);}return{...r,value,planned,done:planned&&!r.needsPlan&&value!==null&&value>=r.target,unit:def.unit,def};}
function supportRows(g,compact=false){const ids=g.habits;return ids.map(id=>{const x=supportStatus(g,id);return '<button class="support-row '+(x.done?'done':'')+(!x.planned?' off-day':'')+'" data-action="support-open" data-id="'+id+'"><span class="support-check">'+(x.done?'✓':!x.planned?'–':x.automatic?'↗':'○')+'</span><span><strong>'+esc(x.label)+'</strong><small>'+(!x.planned?'Не заплановано на цей день':x.needsPlan?'Спершу додай свій особистий орієнтир':(x.value===null?'Ще немає запису':num(x.value,1))+' / '+num(x.target,1)+' '+x.unit+(x.automatic?' · зі щоденника':' · мій запис'))+'</small>'+(!compact?'<em>'+esc(x.def.sub)+'</em>':'')+'</span><b>↗</b></button>';}).join('');}
function smartHabitPanel(){const g=goal(),xs=g.habits.map(id=>supportStatus(g,id)),planned=xs.filter(x=>x.planned),done=planned.filter(x=>x.done);return '<section class="panel supports-home"><div class="panel-head"><div><span class="overline">ТВІЙ НАБІР ПІД ТВОЮ ЦІЛЬ</span><h2>Мої опори</h2></div><button class="text-btn" data-view="supports">'+done.length+' / '+planned.length+' ↗</button></div>'+supportRows(g,true)+'<button class="btn ghost full" data-action="supports-settings">Налаштувати свій набір ↗</button><div class="minimum-card"><h3>Мій мінімум на складний день</h3><p>'+esc(g.minimum)+'</p><button class="text-btn" data-action="minimum">Відзначити маленький крок ↗</button></div></section>';}
function supportsView(){const g=goal(),t=GOAL_TEMPLATES[g.kind]||GOAL_TEMPLATES.custom,xs=g.habits.map(id=>supportStatus(g,id)),planned=xs.filter(x=>x.planned),done=planned.filter(x=>x.done);return pageTop('Опори, в яких є ти.','МІЙ НАБІР / '+g.title,dateControl())+'<section class="supports-hero"><span>'+t.icon+'</span><small>МОЯ ЦІЛЬ</small><h2>'+esc(g.title)+'</h2><p>'+esc(t.line)+'</p><div><strong>'+done.length+' / '+planned.length+'</strong><span>запланованих опор<br>відзначено сьогодні</span></div><button class="btn" data-action="supports-settings">Змінити набір і маленькі кроки ↗</button></section><div class="supports-explain"><b>Не універсальний список справ.</b><p>Ти обираєш свої дії, розмір кроку й дні. Частина опор бачить записи їжі, спорту та сну автоматично. Для власних звичок є ручний запис.</p></div><section class="panel">'+supportRows(g)+'</section>'+(planned.length&&done.length===planned.length?'<button class="coach-link" data-action="quick-mark"><span>ТВОЇ СЬОГОДНІШНІ КРОКИ ВЖЕ Є</span><strong>Відзначити день у календарі ↗</strong></button>':'')+'<section class="panel bottom-space"><h2>Маленькі дії за 7 днів</h2><div class="supports-week">'+Array.from({length:7},(_,i)=>{const d=offset(selectedDate,i-6),a=g.habits.map(id=>supportStatus(g,id,d)).filter(x=>x.planned);return '<div><b>'+a.filter(x=>x.done).length+'/'+a.length+'</b><span>'+new Intl.DateTimeFormat('uk-UA',{weekday:'short',timeZone:'UTC'}).format(dt(d))+'</span></div>';}).join('')+'</div><p class="filter-note">За нинішнім набором і розкладом. Зміна опор може змінити цю довідкову картину; позначки календаря зберігаються окремо.</p></section><button class="daily-context" data-action="plan"><span>✦</span><span><strong>Мій план харчування</strong><small>Розрахувати стартові калорії та БЖВ</small></span><b>↗</b></button><button class="text-btn full" data-view="goals">Усі мої цілі ↗</button>';}
function supportsSettings(reset=false){const g=goal();if(!supportsDraft||reset)supportsDraft={ids:[...(reset?(GOAL_TEMPLATES[g.kind]||GOAL_TEMPLATES.custom).habits:g.habits)],rules:reset?{}:structuredClone(g.supportRules||{})};const draft=supportsDraft;openModal('МОЇ ОПОРИ / МОЯ ВЕРСІЯ','<h2 class="modal-title">Не всі опори.<br>Саме твої.</h2><p class="modal-sub">Ціль: '+esc(g.title)+'. Почни з кількох посильних дій; великий список не обов’язковий.</p><form id="supportsForm">'+Object.entries(SUPPORT_GROUPS).map(([group,name])=>'<details class="supports-group" '+(draft.ids.some(id=>SUPPORT_DEFINITIONS[id]?.group===group)?'open':'')+'><summary>'+name+'</summary>'+Object.entries(SUPPORT_DEFINITIONS).filter(([id,d])=>d.group===group).map(([id,d])=>{const x=supportRule({...g,supportRules:draft.rules},id);return '<div class="support-option"><label class="recipe-checkbox"><input type="checkbox" name="support" value="'+id+'" '+(draft.ids.includes(id)?'checked':'')+'><span><b>'+d.name+'</b><small>'+d.sub+'</small></span></label><details><summary>Мій крок і розклад</summary><div class="form-pair"><label class="form-label">Крок, '+d.unit+'<input type="number" name="target_'+id+'" min="1" max="100000" step="any" value="'+x.target+'"></label><label class="form-label">Коли?<select name="schedule_'+id+'">'+[['daily','Щодня'],['weekdays','Пн–Пт'],['three','Пн, Ср, Пт'],['weekends','Сб–Нд']].map(([k,n])=>'<option value="'+k+'" '+(supportScheduleName(x.days)===k?'selected':'')+'>'+n+'</option>').join('')+'</select></label></div><label class="form-label">Моя назва<input name="label_'+id+'" maxlength="80" value="'+esc(x.label)+'"></label>'+(id==='protein'?'<label class="recipe-checkbox"><input name="follow_protein" type="checkbox" '+(x.followPlan?'checked':'')+'>Брати орієнтир білка з мого особистого плану</label>':'')+(d.auto?'<label class="recipe-checkbox"><input type="checkbox" name="auto_'+id+'" '+(x.automatic?'checked':'')+'>Брати виконання з відповідного щоденника</label>':'')+'</details></div>';}).join('')+'</details>').join('')+'<label class="form-label">Мій мінімум на складний день<input name="minimum" maxlength="180" value="'+esc(g.minimum)+'" required></label><p class="form-error" id="supportsError" role="alert"></p><button class="btn blue full">Зберегти мої опори</button><button class="text-btn full" type="button" data-action="supports-reset">Повернути набір, запропонований для цієї цілі</button></form>');}
function supportScheduleName(days){const str=[...days].sort().join(',');return str==='1,2,3,4,5'?'weekdays':str==='1,3,5'?'three':str==='0,6'?'weekends':'daily';}
function saveSupports(v,data){const ids=data.getAll('support').filter(id=>SUPPORT_DEFINITIONS[id]);if(!ids.length){$('supportsError').textContent='Обери хоча б одну опору.';return;}const g=goal();g.habits=[...new Set(ids)];g.minimum=v.minimum.trim();g.supportRules=Object.fromEntries(ids.map(id=>[id,{target:Math.max(1,Math.min(100000,Number(v['target_'+id])||1)),label:String(v['label_'+id]||SUPPORT_DEFINITIONS[id].name).slice(0,80),days:{daily:[0,1,2,3,4,5,6],weekdays:[1,2,3,4,5],three:[1,3,5],weekends:[0,6]}[v['schedule_'+id]]||[0,1,2,3,4,5,6],followPlan:id==='protein'&&v.follow_protein==='on',automatic:!!SUPPORT_DEFINITIONS[id].auto&&v['auto_'+id]==='on'}]));supportsDraft=null;persist();closeModal();navigate('supports');toast('Твої опори тепер під твій ритм. Календар збережено.');}
function supportOpen(id){if(!goal().habits.includes(id))return;const x=supportStatus(goal(),id);if(x.needsPlan){planModal();return;}modalData={mode:'support',supportId:id};const route={meals:'food',minutes:'move',steps:'move',water:'food',sleep:'sleep',checkin:'coach',protein:'food',strength:'move',mobility:'move'}[x.def.auto];openModal('МІЙ КРОК / '+fdate(selectedDate),'<h2 class="modal-title">'+esc(x.label)+'</h2><p class="modal-sub">Мій крок: '+num(x.target,1)+' '+x.unit+'. '+(!x.planned?'На цей день опора не запланована.':'')+'</p>'+(x.automatic?'<div class="workout-estimate"><strong>'+(x.value===null?'Ще без запису':num(x.value,1)+' '+x.unit)+'</strong><p>Ця опора бере дані зі щоденника. Внеси або уточни їх там; автоматична позначка оновиться сама.</p></div><button class="btn blue full" data-view="'+route+'">Відкрити відповідний щоденник ↗</button><button class="text-btn full" data-action="supports-settings">Змінити на ручну позначку</button>':'<form id="supportLogForm"><label class="form-label">Зроблено, '+x.unit+'<input type="number" name="value" min="0" max="100000" step="any" value="'+(x.value??x.target)+'" required></label><p class="note">Запис за '+fdate(selectedDate)+'. Замінимо значення цього дня, а не додамо його вдруге.</p><p id="supportLogError" class="form-error" role="alert"></p><button class="btn blue full">Зберегти мій крок</button></form>'));}
const PLAN_PAL={seated:{value:1.4,label:'Майже весь день сиджу, мало руху'},light:{value:1.6,label:'Переважно сиджу, є прогулянки / легкі заняття'},mixed:{value:1.8,label:'Багато ходжу, є регулярні тренування'},physical:{value:2.0,label:'Фізична робота або дуже рухливі дні'}};
function nutritionEstimate(v){const w=Number(v.weight),h=Number(v.height),a=Number(v.age),pal=PLAN_PAL[v.activityLevel]?.value,sex=v.sex;const fail=message=>({ok:false,message});if(!Number.isFinite(w)||w<30||w>300||!Number.isFinite(h)||h<120||h>230||!Number.isFinite(a)||a<19||a>78||!pal||!['female','male'].includes(sex))return fail('Для цієї моделі потрібні вік 19–78 років, вага 30–300 кг, зріст 120–230 см, параметр формули й активність. Щоденник можна вести без розрахунку.');if(v.individual==='on'||v.individual===true)return fail('Для вагітності, грудного вигодовування або індивідуального лікувального харчування автоматичний стартовий план не застосовуємо. Можна внести орієнтири, узгоджені з фахівцем.');const bmi=w/(h/100)**2,purpose=['lose','gain','maintain'].includes(v.purpose)?v.purpose:'maintain';if(purpose==='lose'&&bmi<18.5)return fail('Для введеного зросту й ваги не пропонуємо автоматичне зниження калорій. Можна обрати підтримання та індивідуально обговорити свою ціль.');const resting=10*w+6.25*h-5*a+(sex==='male'?5:-161),maintenance=resting*pal,adjust=purpose==='lose'?-.1:purpose==='gain'?.05:0,calories=Math.round(maintenance*(1+adjust)/10)*10;if(calories<1500)return fail('Результат виходить нижчим за 1500 ккал. У цьому загальному калькуляторі такий стартовий план не формуємо; це обмеження продукту, а не універсальна особиста норма. Залиши власні орієнтири або уточни їх із фахівцем.');const protein=v.balance==='protein'?.25:.20,fat=.30,carb=1-protein-fat;return{ok:true,resting,maintenance,calories,p:Math.round(calories*protein/4),f:Math.round(calories*fat/9),c:Math.round(calories*carb/4),purpose,pal,adjust,proteinPct:protein*100,fatPct:30,carbPct:Math.round(carb*100),snapshot:{weight:w,height:h,age:a,sex,activityLevel:v.activityLevel,purpose,balance:v.balance==='protein'?'protein':'balanced'}};}
function planModal(){const p=state.profile,old=state.nutritionPlan?.snapshot||{},purpose=old.purpose||GOAL_TEMPLATES[goal().kind]?.nutrition||'maintain';modalData={mode:'plan'};openModal('МІЙ ПЛАН / СТАРТОВА ОЦІНКА','<h2 class="modal-title">Під тебе.<br>З поясненням цифр.</h2><p class="modal-sub">Орієнтир для дорослої людини, не вимірювання обміну речовин. Результат можна змінити; дата цілі не змушує пришвидшувати темп.</p><form id="nutritionPlanForm"><div class="form-triple"><label class="form-label">Вік<input name="age" type="number" min="19" max="78" value="'+esc(p.age||'')+'" required></label><label class="form-label">Зріст, см<input name="height" type="number" min="120" max="230" value="'+esc(p.height||'')+'" required></label><label class="form-label">Вага, кг<input name="weight" type="number" min="30" max="300" step=".1" value="'+esc(p.weight||'')+'" required></label></div><label class="form-label">Параметр формули Mifflin–St Jeor<select name="sex" required><option value="">Обрати</option><option value="female" '+(p.sex==='female'?'selected':'')+'>Жіноча формула</option><option value="male" '+(p.sex==='male'?'selected':'')+'>Чоловіча формула</option></select><small>У вихідному дослідженні різні коефіцієнти для двох груп. Якщо модель не підходить, можна залишити ручні орієнтири.</small></label><label class="form-label">Звичайна активність за тиждень<select name="activityLevel" required><option value="">Обрати чесний звичайний ритм</option>'+Object.entries(PLAN_PAL).map(([k,x])=>'<option value="'+k+'" '+(p.activityLevel===k?'selected':'')+'>'+x.label+'</option>').join('')+'</select><small>Включає звичайні тренування. Калорії записаних сесій не додаються вдруге.</small></label><label class="form-label">Напрям<select name="purpose">'+[['maintain','Підтримання ваги'],['lose','Поступове зниження · старт −10%'],['gain','Поступовий набір · старт +5%']].map(([k,n])=>'<option value="'+k+'" '+(purpose===k?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label class="form-label">Стартовий баланс БЖВ<select name="balance"><option value="balanced" '+(old.balance!=='protein'?'selected':'')+'>Б 20% · Ж 30% · В 50%</option><option value="protein" '+(old.balance==='protein'?'selected':'')+'>Б 25% · Ж 30% · В 45%</option></select><small>Загальні варіанти в межах дорослих AMDR, не індивідуальна спортивна чи лікувальна норма білка.</small></label><label class="recipe-checkbox"><input type="checkbox" name="individual">Вагітність, грудне вигодовування або індивідуальний лікувальний план</label><div id="planResult" class="plan-result" aria-live="polite"></div><button class="btn blue full" id="applyPlan" type="submit">Застосувати стартові орієнтири</button></form><details class="catalog-method"><summary>Метод і межі точності</summary><p><a href="https://pubmed.ncbi.nlm.nih.gov/2305711/" target="_blank" rel="noopener">Mifflin–St Jeor (1990)</a>: 10 × кг + 6,25 × см − 5 × вік + 5 (чоловіча) або −161 (жіноча). Потім множимо на обраний PAL 1,4 / 1,6 / 1,8 / 2,0. Це загальні категорії активності, а не вимірювання твого дня.</p><p><a href="https://www.niddk.nih.gov/bwp" target="_blank" rel="noopener">NIDDK</a> описує типовий PAL 1,4–2,5. Тут не відтворюється динамічна модель NIDDK; використовуємо простішу стартову оцінку. −10% і +5% — обережні налаштування цього продукту, не точний прогноз зміни ваги.</p><p><a href="https://www.canada.ca/en/health-canada/services/food-nutrition/healthy-eating/dietary-reference-intakes/tables/reference-values-macronutrients.html" target="_blank" rel="noopener">AMDR для дорослих</a>: Б 10–35%, Ж 20–35%, В 45–65%. Індивідуальні потреби можуть відрізнятися.</p><p>Почни зі спостережень протягом 2–4 тижнів: самопочуття, повнота записів, середні значення ваги. Немає гарантованої похибки чи автоматично «найточнішої» цифри. Для особистої оцінки метаболізму потрібні відповідні вимірювання.</p></details>');$('nutritionPlanForm').oninput=renderNutritionPlan;renderNutritionPlan();}
function renderNutritionPlan(){const v=Object.fromEntries(new FormData($('nutritionPlanForm')).entries()),x=nutritionEstimate(v);$('applyPlan').disabled=!x.ok;$('planResult').innerHTML=x.ok?'<span>СТАРТОВИЙ ОРІЄНТИР НА ДЕНЬ</span><strong>≈ '+num(x.calories)+' <small>ккал</small></strong><div class="plan-macros"><b>Б '+x.p+' г</b><b>Ж '+x.f+' г</b><b>В '+x.c+' г</b></div><p>Обмін у спокої ≈ '+num(x.resting)+' · підтримання ≈ '+num(x.maintenance)+' ккал. '+(x.purpose==='lose'?'Від підтримання віднято 10%.':x.purpose==='gain'?'До підтримання додано 5%.':'Без зміни від підтримання.')+'</p><small>Округлено до 10 ккал; грами — до цілих. Один день і цифра на вагах не перевіряють точність моделі.</small>':'<p>'+esc(x.message)+'</p>';}
function applyNutritionPlan(v){const x=nutritionEstimate(v);if(!x.ok){$('planResult').textContent=x.message;return;}for(const k of ['weight','height','age'])state.profile[k]=String(x.snapshot[k]);state.profile.sex=v.sex;state.profile.activityLevel=v.activityLevel;state.settings.calories=x.calories;state.settings.macros={p:x.p,f:x.f,c:x.c};state.nutritionPlan={...x,applied:today(),method:'Mifflin-St Jeor + PAL v1'};persist();closeModal();navigate('coach');toast('Стартові орієнтири застосовано. Їх можна змінити у своєму темпі.');}
function normalizeCustomFoods(items,number,id,str){if(items===undefined)return[];if(!Array.isArray(items)||items.length>500)throw Error('Некоректна власна база');return items.map(p=>{if(!p||typeof p.name!=='string'||!p.name.trim())throw Error('Некоректний продукт');const serving=number(p.serving,10000);if(serving<=0)throw Error('Некоректна порція');return{id:id(p.id),name:str(p.name,140),brand:str(p.brand,80)||'Мій продукт',category:FOOD_CATEGORIES[p.category]?p.category:'other',unit:p.unit==='ml'?'ml':'g',basis:100,serving,kcal:number(p.kcal,10000),p:number(p.p,100,true),f:number(p.f,100,true),c:number(p.c,100,true),quality:'user',url:safeSourceURL(p.url),checked:validDate(p.checked)?p.checked:'',localized:true,emoji:p.unit==='ml'?'🥤':'◌'};});}
function normalizeSupportRules(value,habits,number,str){if(!value)return{};if(typeof value!=='object'||Array.isArray(value))throw Error('Некоректні опори');const out={};for(const id of habits){const r=value[id];if(!r)continue;if(!Array.isArray(r.days)||!r.days.length||r.days.length>7||r.days.some(n=>!Number.isInteger(n)||n<0||n>6))throw Error('Некоректний розклад');const target=number(r.target,100000);if(target<=0)throw Error('Некоректний крок');out[id]={target,followPlan:id==='protein'&&r.followPlan!==false,label:str(r.label,80)||SUPPORT_DEFINITIONS[id].name,days:[...new Set(r.days)],automatic:!!SUPPORT_DEFINITIONS[id].auto&&r.automatic===true};}return out;}
function normalizeSupportValues(v,number){if(!v)return{};if(typeof v!=='object'||Array.isArray(v)||Object.keys(v).length>1000)throw Error('Некоректні позначки');return Object.fromEntries(Object.entries(v).filter(([k])=>/^[A-Za-z0-9_-]{1,160}$/.test(k)).map(([k,n])=>[k,number(n,100000)]));}
function onboardSmartView(){const o=onboard,t=GOAL_TEMPLATES[o.kind]||GOAL_TEMPLATES.custom;let body='<div class="step-dots">'+[0,1,2].map(i=>'<i class="'+(i<=o.step?'active':'')+'"></i>').join('')+'</div><form id="onboardForm">';const choice=([k,x])=>'<button type="button" class="goal-choice '+(o.kind===k?'selected':'')+'" data-action="onboard-kind" data-id="'+k+'"><span>'+x.icon+'</span><b>'+x.name+'</b><small>'+x.line+'</small></button>';if(o.step===0)body+='<h2 class="modal-title">У кожного —<br>свій напрям.</h2><p class="modal-sub">Яка думка найбільше схожа на твою? Потім підберемо опори під цю ціль.</p><div class="goal-choices">'+Object.entries(GOAL_TEMPLATES).slice(0,6).map(choice).join('')+'</div><details class="more-goals" '+(!['lose','gain','muscle','form','energy','consistent'].includes(o.kind)?'open':'')+'><summary>Ще напрями: рух, сон, навчання, робота й моє життя</summary><div class="goal-choices">'+Object.entries(GOAL_TEMPLATES).slice(6).map(choice).join('')+'</div></details><label class="form-label">Як до тебе звертатися?<input name="name" maxlength="40" value="'+esc(o.name)+'" required placeholder="Твоє ім’я"></label>';if(o.step===1)body+='<h2 class="modal-title">Твоя ціль.<br>Твій горизонт.</h2><p class="modal-sub">'+esc(t.line)+'</p><label class="form-label">Моя назва цілі<input name="title" maxlength="90" value="'+esc(o.title)+'" required></label><div class="form-pair"><label class="form-label">Початок<input type="date" name="start" value="'+o.start+'" required></label><label class="form-label">Моя дата<input type="date" name="end" value="'+o.end+'" required></label></div><div class="pill-row">'+[1,3,4,6].map(n=>'<button type="button" class="pill" data-action="period" data-value="'+n+'">'+n+' міс.</button>').join('')+'</div><label class="form-label">Мій мінімум у складний день<input name="minimum" maxlength="180" value="'+esc(o.minimum)+'" required><small>Це маленька посильна дія, а не обов’язкова ідеальність.</small></label>';if(o.step===2)body+='<h2 class="modal-title">Те, на що<br>ти спиратимешся.</h2><p class="modal-sub">Пропонуємо набір для «'+esc(t.name)+'». Залиш свої опори, решту сміливо прибирай.</p>'+Object.entries(SUPPORT_GROUPS).map(([group,n])=>'<details class="supports-group" '+(o.habits.some(id=>SUPPORT_DEFINITIONS[id]?.group===group)?'open':'')+'><summary>'+n+'</summary>'+Object.entries(SUPPORT_DEFINITIONS).filter(([id,x])=>x.group===group).map(([id,x])=>'<div class="onboard-support"><label class="recipe-checkbox"><input type="checkbox" name="habit" value="'+id+'" '+(o.habits.includes(id)?'checked':'')+'><span><b>'+x.name+'</b><small>'+x.sub+(t.habits.includes(id)?' · під твою ціль':'')+'</small></span></label><label class="support-small-target">Мій крок<input type="number" name="habitTarget_'+id+'" min="1" max="100000" step="any" value="'+(o['habitTarget_'+id]||x.target)+'">'+x.unit+'</label></div>').join('')+'</details>').join('')+'<label class="form-label">Мій звичайний день<select name="activityLevel">'+Object.entries(ACTIVITY_LEVELS).map(([k,n])=>'<option value="'+k+'" '+(o.activityLevel===k?'selected':'')+'>'+n+'</option>').join('')+'</select></label><details><summary class="small">Мої параметри · за бажанням</summary><div class="form-triple">'+[['age','Вік',18,100],['height','Зріст, см',100,250],['weight','Вага, кг',30,400]].map(([k,n,min,max])=>'<label class="form-label">'+n+'<input name="'+k+'" type="number" min="'+min+'" max="'+max+'" step="'+(k==='weight'?'.1':'1')+'" value="'+esc(o[k]||'')+'"></label>').join('')+'</div><label class="form-label">Моя ціль ваги · за бажанням<input name="targetWeight" type="number" min="30" max="400" step=".1" value="'+esc(o.targetWeight||'')+'"></label><label class="form-label">Власний орієнтир ккал, якщо вже є<input name="calories" type="number" min="1" max="10000" value="'+esc(o.calories||'')+'"></label></details><label class="recipe-checkbox"><input type="checkbox" name="calculate" '+(t.nutrition?'checked':'')+'>Після створення показати персональний розрахунок калорій і БЖВ</label><p class="filter-note">Розрахунок окремо уточнить параметри. Опори, розклад і орієнтири можна змінювати згодом.</p>';body+='<p class="form-error" id="formError" role="alert"></p><div class="form-actions">'+(o.step?'<button class="btn ghost" type="button" data-action="onboard-back">Назад</button>':'')+'<button class="btn blue" type="submit">'+(o.step===2?'Створити мій шлях ↗':'Далі ↗')+'</button></div></form>';openModal('МІЙ СТАРТ / '+(o.step+1)+' З 3',body);}
